def topological_unique(adjacency):
    degree = indegrees(adjacency)
    queue = []
    for vertex in range(len(adjacency)):
        if degree[vertex] == 0:
            queue.append(vertex)
    head = 0
    unique = True
    while head < len(queue):
        if len(queue) - head > 1:
            unique = False
