def heap_swap(heap, left, right):
    saved = heap[left]
    heap[left] = heap[right]
    heap[right] = saved

def sift_up(heap, index):
    while index > 0:
        parent = (index - 1) // 2
        if heap[parent] <= heap[index]:
            return
        heap_swap(heap, parent, index)
        index = parent

def heap_push(heap, value):
    heap.append(value)
    sift_up(heap, len(heap) - 1)

def sift_down(heap, index, size):
    while 2 * index + 1 < size:
        child = 2 * index + 1
        right = child + 1
        if right < size and heap[right] < heap[child]:
            child = right
        if heap[index] <= heap[child]:
            return
        heap_swap(heap, index, child)
        index = child

def heap_pop(heap):
    if len(heap) == 0:
        return None
    smallest = heap[0]
    last = heap.pop()
    if len(heap) > 0:
        heap[0] = last
        sift_down(heap, 0, len(heap))
    return smallest

def topological_smallest(adjacency):
    degree = indegrees(adjacency)
    heap = []
    for vertex in range(len(adjacency)):
        if degree[vertex] == 0:
            heap_push(heap, vertex)
    order = []
    while len(heap) > 0:
        source = heap_pop(heap)
        order.append(source)
        for target in adjacency[source]:
            degree[target] = degree[target] - 1
            if degree[target] == 0:
                heap_push(heap, target)
    if len(order) != len(adjacency):
        return None
    return order

