def dfs_topology(adjacency):
    n = len(adjacency)
    color = filled(n, 0)
    parent = filled(n, None)
    finished = []
    for root in range(n):
        if color[root] == 0:
            color[root] = 1
            stack = [[root, 0]]
            while len(stack) > 0:
                frame = stack[-1]
                source = frame[0]
                if frame[1] == len(adjacency[source]):
                    stack.pop()
                    color[source] = 2
                    finished.append(source)
                else:
                    target = adjacency[source][frame[1]]
                    frame[1] = frame[1] + 1
                    if color[target] == 0:
                        parent[target] = source
                        color[target] = 1
                        stack.append([target, 0])
                    elif color[target] == 1:
                        reverse_path = []
                        current = source
                        while current != target:
                            reverse_path.append(current)
                            current = parent[current]
                        cycle = [target]
                        for i in range(len(reverse_path) - 1, -1, -1):
                            cycle.append(reverse_path[i])
                        cycle.append(target)
                        return {"order": [], "cycle": cycle}
    order = []
    for i in range(len(finished) - 1, -1, -1):
        order.append(finished[i])
    return {"order": order, "cycle": []}

